Property Grid > Int List  #region Collection will display as a ComboBox in PropertyGrid on the fly.    public class FileListProperty {        public static List<int> RadiusList = new List<int>() { 20 };        public static List<int> ThicknessList = new List<int>() { 6, 8 };        public static List<string> FilesList = new List<string>() {            "radius_20_offset_3_thickness_6.png",            "radius_20_offset_5_thickness_8.png"        };    }    public class ThicknessPropertyConverter : Int32Converter {        public override bool GetStandardValuesSupported(ITypeDescriptorContext context) {            //true means show a combobox            return true;        }        public override bool GetStandardValuesExclusive(ITypeDescriptorContext context) {            //true will limit to list. false will show the list,             //but allow free-form entry            return true;        }        public override System.ComponentModel.TypeConverter.StandardValuesCollection               GetStandardValues(ITypeDescriptorContext context) {            return new StandardValuesCollection(FileListProperty.ThicknessList);        }    }    public class RadiusPropertyConverter : Int32Converter {        public override bool GetStandardValuesSupported(ITypeDescriptorContext context) {            //true means show a combobox            return true;        }        public override bool GetStandardValuesExclusive(ITypeDescriptorContext context) {            //true will limit to list. false will show the list,             //but allow free-form entry            return true;        }        public override System.ComponentModel.TypeConverter.StandardValuesCollection               GetStandardValues(ITypeDescriptorContext context) {            return new StandardValuesCollection(FileListProperty.RadiusList);        }    }    #endregion         [CategoryAttribute("VZHLED"),            DisplayName("Tloušťka okraje"),            DescriptionAttribute("Tloušťka okraje"),            TypeConverter(typeof(ThicknessPropertyConverter))        ]        int BorderThickness { get; set; }        [CategoryAttribute("VZHLED"),            DisplayName("Poloměr zaoblení"),            DescriptionAttribute("Poloměr zaoblení"),            TypeConverter(typeof(RadiusPropertyConverter))        ]        int BackgroundRadius { get; set; }  public int BorderRadius {            //When first loaded set property with the first item in the rule list.            get {                int S = -1;                if (_borderRadius == -1) {                    if (FileListProperty.RadiusList.Count > 0) {                        //Sort the list before displaying it                        Array.Sort(FileListProperty.RadiusList.ToArray());                        S = FileListProperty.RadiusList[0];                    }                } else {                    S = _borderRadius;                }                return S;            }            set {                _borderRadius = value;            }        }        public int BorderThickness {            //When first loaded set property with the first item in the rule list.            get {                int S = -1;                if (_borderThickness == -1) {                    if (FileListProperty.ThicknessList.Count > 0) {                        //Sort the list before displaying it                        Array.Sort(FileListProperty.ThicknessList.ToArray());                        S = FileListProperty.ThicknessList[0];                    }                } else {                    S = _borderThickness;                }                return S;            }            set {                _borderThickness = value;            }        }        private int _borderThickness = -1;        private int _borderRadius = -1;